// Server state through TanStack Query (ADR-0009). One query key family per resource; mutations invalidate them.
import { keepPreviousData, useQuery, useQueryClient, type QueryClient } from "@tanstack/react-query";
import { PAGINATION } from "@mth/shared";
import {
  ApiError,
  api,
  apiRequest,
  asIdentityProbe,
  getSessionGeneration,
  isSessionChangedError,
  markSessionActive,
  noteSessionIdentity,
  sessionIdentityKey,
  setCsrfToken,
} from "./client.ts";
import type {
  AuditEvent,
  CharterVersion,
  CharterView,
  Decision,
  GateSubmission,
  GateSubmissionView,
  GateView,
  JourneyPainPoint,
  MethodologyCatalogue,
  NorthStar,
  RoleAccountability,
  TeamAssignment,
  TomCanvasCellView,
  TomWorkshopItem,
  BusinessUnit,
  Me,
  Organization,
  Page,
  PermissionEntry,
  Role,
  RoleAssignment,
  Transformation,
  TransformationSort,
  User,
} from "./types.ts";

export const keys = {
  me: ["me"] as const,
  organizations: ["organizations"] as const,
  organization: (id: string) => ["organizations", id] as const,
  businessUnits: (orgId: string) => ["business-units", orgId] as const,
  businessUnit: (id: string) => ["business-unit", id] as const,
  users: (params: object) => ["users", params] as const,
  user: (id: string) => ["user", id] as const,
  roles: ["roles"] as const,
  permissions: ["permissions"] as const,
  assignments: (params: object) => ["role-assignments", params] as const,
  transformations: (params: object) => ["transformations", params] as const,
  transformation: (id: string) => ["transformation", id] as const,
  audit: (id: string, cursor: string | null) => ["transformation-audit", id, cursor] as const,
};

/** No retry for 4xx (they will not change by retrying); two retries for network/5xx. */
export function shouldRetry(failureCount: number, error: unknown): boolean {
  if (error instanceof ApiError && error.status < 500) return false;
  if (isSessionChangedError(error)) return false; // F-DG2-530: the answer belongs to a previous identity
  return failureCount < 2;
}

// ------------------------------------------------------------------------------------------------ session
/**
 * GET /me. A success makes the session phase "active"; a 401 while it was active is a session end like any other
 * request's (apps/web/src/api/client.ts), and a 401 with no session yet is just "not signed in".
 * F-DG2-500: another identity (user or session) than the last one this document saw first removes every
 * session-scoped query (noteSessionIdentity), before the answer is stored and so before anything renders under it.
 */
export function fetchMe(): Promise<Me> {
  // F-DG2-570: page GETs sent while this /me is in flight wait until its identity has been noted (api/client.ts).
  return asIdentityProbe(async () => {
    const me = (await apiRequest<Me>("/api/v1/me", { sessionProbe: true })).data;
    noteSessionIdentity(sessionIdentityKey(me));
    setCsrfToken(me.csrfToken);
    markSessionActive();
    return me;
