export function useTransformationAudit(id: string, cursor: string | null, enabled: boolean) {
  return useQuery({
    queryKey: keys.audit(id, cursor),
    queryFn: () =>
      api.get<Page<AuditEvent>>(`/api/v1/transformations/${id}/audit`, { limit: 10, ...(cursor ? { cursor } : {}) }),
