+export function useRegister<T>(tid: string, resource: string, query: Record<string, string> = {}, enabled = true) {
+  return useQuery({
+    queryKey: p2Keys.register(tid, resource, query),
+    queryFn: () => fetchAllPages<T>(`${base(tid)}/${resource}`, query),
+    enabled: Boolean(tid) && enabled,
+    retry: shouldRetry,
+  });
+}
+
+export function useCharter(tid: string) {
+  return useQuery({
+    queryKey: p2Keys.charter(tid),
+    queryFn: () => orNull(() => api.get<CharterView>(`${base(tid)}/charter`), "charter_not_found"),
+    retry: shouldRetry,
+  });
+}
+
+export function useCharterVersions(tid: string, enabled = true) {
+  return useQuery({
+    queryKey: p2Keys.charterVersions(tid),
+    queryFn: () => fetchAllPages<CharterVersion>(`${base(tid)}/charter/versions`),
+    enabled,
+    retry: shouldRetry,
+  });
+}
+
+export function useNorthStar(tid: string) {
+  return useQuery({
+    queryKey: p2Keys.northStar(tid),
+    queryFn: () => orNull(() => api.get<NorthStar>(`${base(tid)}/north-star`), "north_star_not_found"),
+    retry: shouldRetry,
+  });
+}
+
+export function useNorthStarHistory(tid: string, enabled = true) {
+  return useQuery({
+    queryKey: p2Keys.northStarHistory(tid),
+    queryFn: () => fetchAllPages<NorthStar>(`${base(tid)}/north-star/history`),
+    enabled,
+    retry: shouldRetry,
+  });
+}
+
+export function useTomCanvas(tid: string) {
+  return useQuery({
+    queryKey: p2Keys.canvas(tid),
+    queryFn: () => api.get<{ cells: TomCanvasCellView[] }>(`${base(tid)}/tom-canvas`),
+    retry: shouldRetry,
+  });
+}
+
+/** The canonical decision register filtered by kind (`design` = T04 Design Decision Log). */
+export function useDecisions(tid: string, kind: "design" | "gate" | "executive") {
+  return useQuery({
+    queryKey: p2Keys.decisions(tid, kind),
+    queryFn: () => fetchAllPages<Decision>("/api/v1/decisions", { transformationId: tid, kind }),
+    retry: shouldRetry,
+  });
+}
+
+export function useGates(tid: string) {
+  return useQuery({
+    queryKey: p2Keys.gates(tid),
+    queryFn: () => api.get<{ items: GateView[] }>(`${base(tid)}/gates`),
+    retry: shouldRetry,
+  });
+}
+
+export function useGate(tid: string, code: string) {
+  return useQuery({
+    queryKey: p2Keys.gate(tid, code),
+    queryFn: () => api.get<GateView>(`${base(tid)}/gates/${code}`),
+    retry: shouldRetry,
+  });
+}
+
+export function useGateSubmissions(tid: string, code: string) {
+  return useQuery({
+    queryKey: p2Keys.gateSubmissions(tid, code),
+    queryFn: () => fetchAllPages<GateSubmission>(`${base(tid)}/gates/${code}/submissions`),
+    retry: shouldRetry,
+  });
+}
+
+export function useGateSubmission(tid: string, code: string, no: number | null) {
+  return useQuery({
+    queryKey: p2Keys.gateSubmission(tid, code, no ?? 0),
+    queryFn: () => api.get<GateSubmissionView>(`${base(tid)}/gates/${code}/submissions/${no}`),
+    enabled: no !== null,
+    retry: shouldRetry,
+  });
+}
+
+/** The transformation team (active scoped assignments here and inherited), used for owner pickers. */
+export function useTeam(tid: string) {
+  return useQuery({
+    queryKey: p2Keys.team(tid),
+    queryFn: () => fetchAllPages<TeamAssignment>(`${base(tid)}/scoped-assignments`),
+    retry: shouldRetry,
+    staleTime: 60_000,
+  });
+}
+
+/** Accountability text per role (B0018 verbatim for the six source roles; platform text for the others). */
+export function useRoleAccountabilities() {
+  return useQuery({
+    queryKey: p2Keys.roleAccountabilities,
+    queryFn: async () => (await api.get<{ items: RoleAccountability[] }>("/api/v1/role-accountabilities")).items,
+    retry: shouldRetry,
+    staleTime: 5 * 60_000,
+  });
+}
+
+export function usePainPoints(tid: string, journeyId: string | null) {
+  return useRegister<JourneyPainPoint>(tid, `journeys/${journeyId}/pain-points`, {}, journeyId !== null);
+}
+
+export function useWorkshopItems(tid: string, workshopId: string | null) {
+  return useRegister<TomWorkshopItem>(tid, `tom-workshops/${workshopId}/items`, {}, workshopId !== null);
+}
+
+/**
+ * Refreshes everything of one transformation after a P2 mutation (registers, live gate readiness, header, phase).
+ * F-DG2-530 (T-DG2-FE15): resolves to whether the session generation it began under is still current, so a success
+ * continuation is written `if (!(await refresh())) return;` and closes no dialog and shows no notice for a session
+ * that has been replaced meanwhile (see auth/sessionBound.ts).
+ */
+export function useP2Refresh(tid: string): () => Promise<boolean> {
+  const queryClient = useQueryClient();
+  return async () => {
+    const generation = getSessionGeneration();
+    await Promise.all([
+      queryClient.invalidateQueries({ queryKey: p2Keys.all(tid) }),
+      queryClient.invalidateQueries({ queryKey: keys.transformation(tid) }),
+    ]);
+    return getSessionGeneration() === generation;
+  };
+}
+
+// ------------------------------------------------------------------------------------------------ P3 (DG3)
+// Query-key factory for the P3 screens (T-DG3-FE-A0 seam; p3-work-split §4). FE-B and FE-C do not edit api/**: they
+// write their hooks in pages/<feature>/api.ts with these keys and api/client.ts. Every P3 key is
+// [<feature>, transformationId, ...], so useP3Refresh() refreshes all of them for one transformation. Global
+// catalogues (dependency types, formula examples) have no transformation id.
+//
+// ADR-0023 §3: ["roadmap", transformationId] is the ONE cache entry the roadmap timeline, table and work board share;
+// moving a milestone updates (or invalidates) that entry and all three views follow. Never add a per-view roadmap key.
+
+/** The P3 feature roots whose second key element is the transformation id. */
+export const P3_FEATURES = [
+  "portfolio",
+  "readiness",
+  "outcome-hierarchy",
+  "dispensations",
+  "prioritization",
+  "roadmap",
+  "dependencies",
+  "capacity",
+  "business-cases",
+  "benefit-formulas",
+] as const;
+export type P3Feature = (typeof P3_FEATURES)[number];
+
+export const p3Keys = {
+  // FE-A: portfolio (T05), initiative links, deliverables, milestones, selection and funding history.
+  portfolio: (tid: string) => ["portfolio", tid] as const,
+  initiatives: (tid: string, query: Record<string, string> = {}) => ["portfolio", tid, "initiatives", query] as const,
+  initiative: (tid: string, initiativeId: string) => ["portfolio", tid, "initiative", initiativeId] as const,
+  /** One sub-resource of an initiative: "gap-links", "outcome-contributions", "decision-links", "deliverables", … */
+  initiativePart: (tid: string, initiativeId: string, part: string) =>
+    ["portfolio", tid, "initiative", initiativeId, part] as const,
+  readiness: (tid: string) => ["readiness", tid] as const,
+  outcomeHierarchy: (tid: string) => ["outcome-hierarchy", tid] as const,
+  dispensations: (tid: string) => ["dispensations", tid] as const,
+  // FE-B: prioritization, roadmap, dependencies, capacity.
+  prioritization: (tid: string) => ["prioritization", tid] as const,
+  /** One part of the prioritization view: "weight-sets", "rankings", "ranking-history", "overrides", … */
+  prioritizationPart: (tid: string, part: string, ...rest: (string | number)[]) =>
+    ["prioritization", tid, part, ...rest] as const,
+  /** ADR-0023 §3: the single entry shared by the roadmap timeline, table and work board. */
+  roadmap: (tid: string) => ["roadmap", tid] as const,
+  dependencies: (tid: string) => ["dependencies", tid] as const,
+  dependencyTypes: ["dependency-types"] as const,
+  capacity: (tid: string) => ["capacity", tid] as const,
+  // FE-C: business cases and T09 benefit formulas.
+  businessCases: (tid: string) => ["business-cases", tid] as const,
+  businessCase: (tid: string, businessCaseId: string) => ["business-cases", tid, businessCaseId] as const,
+  /** One part of a business case: "lines", "totals", "baseline-validation", … */
+  businessCasePart: (tid: string, businessCaseId: string, part: string) =>
+    ["business-cases", tid, businessCaseId, part] as const,
+  benefitFormulas: (tid: string) => ["benefit-formulas", tid] as const,
+  benefitFormula: (tid: string, formulaId: string) => ["benefit-formulas", tid, formulaId] as const,
+  /** One part of a formula: "versions", or ["versions", n, "calculations" | "validation"]. */
+  benefitFormulaPart: (tid: string, formulaId: string, ...rest: (string | number)[]) =>
+    ["benefit-formulas", tid, formulaId, ...rest] as const,
+  benefitFormulaExamples: ["benefit-formula-examples"] as const,
+};
+
+/** Whether a query key belongs to the P3 data of this transformation ([<P3 feature>, tid, ...]). */
+export function isP3KeyOf(tid: string, key: readonly unknown[]): boolean {
+  return (P3_FEATURES as readonly unknown[]).includes(key[0]) && key[1] === tid;
+}
+
+/**
+ * Refreshes everything of one transformation after a P3 mutation: every P3 feature entry, the P2 registers and LIVE
+ * gate readiness (G4 depends on the portfolio), and the transformation header. Like useP2Refresh, it resolves to
+ * whether the session generation it began under is still current: `if (!(await refresh())) return;`.
+ */
+export function useP3Refresh(tid: string): () => Promise<boolean> {
+  const queryClient = useQueryClient();
+  return async () => {
+    const generation = getSessionGeneration();
+    await Promise.all([
+      queryClient.invalidateQueries({ predicate: (q) => isP3KeyOf(tid, q.queryKey) }),
+      queryClient.invalidateQueries({ queryKey: p2Keys.all(tid) }),
+      queryClient.invalidateQueries({ queryKey: keys.transformation(tid) }),
+    ]);
+    return getSessionGeneration() === generation;
+  };
+}

